\set ON_ERROR_STOP on
create function pg_temp.check_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end;$$;
create function pg_temp.denied(command text,expected text,label text) returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate<>expected then raise exception 'FAIL: % expected % got % (%)',label,expected,sqlstate,sqlerrm;end if;raise notice 'PASS: %',label;return;end;raise exception 'FAIL: % unexpectedly succeeded',label;end;$$;
insert into auth.users(id,email_confirmed_at,is_anonymous) select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,case when n=807 then null else now() end,n=808 from generate_series(801,808)n;
insert into public.tenants(id,name,time_zone) values('81000000-0000-0000-0000-000000000001','Time Off synthetic A','Europe/London'),('81000000-0000-0000-0000-000000000002','Time Off synthetic B','UTC');
insert into public.tenant_memberships(tenant_id,user_id,display_name,role) select case when n=806 then '81000000-0000-0000-0000-000000000002'::uuid else '81000000-0000-0000-0000-000000000001'::uuid end,('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Leave actor '||n,case n when 801 then 'owner' when 802 then 'admin' when 803 then 'manager' when 806 then 'owner' else 'employee' end from generate_series(801,808)n;
insert into public.agents(id,tenant_id,user_id,first_name,last_name,phone,created_by) select ('84000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'81000000-0000-0000-0000-000000000001',('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Synthetic',n::text,'+447700902'||n,'00000000-0000-0000-0000-000000000801' from generate_series(801,805)n;
create function pg_temp.save(c jsonb,operation uuid default gen_random_uuid()) returns jsonb language sql as $$select public.save_time_off('81000000-0000-0000-0000-000000000001',operation,c)$$;
create function pg_temp.create_type(n text default 'Vacation') returns jsonb language sql as $$select jsonb_build_object('action','create_type','name',n,'description','Synthetic retained type description','paid',true)$$;
create function pg_temp.request(n text default 'Synthetic private note',d date default '2026-10-24',e date default '2026-10-26') returns jsonb language sql as $$select jsonb_build_object('action','request','agentId',(select id from public.agents where tenant_id='81000000-0000-0000-0000-000000000001' and user_id=auth.uid() and status='active'),'typeId',(select id from public.time_off_types where name='Vacation'),'startDate',d,'endDate',e,'note',n)$$;
create function pg_temp.action(a text,n text,why text default '') returns jsonb language sql as $$select jsonb_build_object('action',a,'requestId',(select id from public.time_off_requests where note=n limit 1),'revision',(select revision from public.time_off_requests where note=n limit 1))||case when a='withdraw' then '{}'::jsonb else jsonb_build_object('reason',why) end$$;
do $$declare t text;p text;begin foreach t in array array['time_off_types','time_off_requests','time_off_audit'] loop perform pg_temp.check_true((select relrowsecurity from pg_class where oid=('public.'||t)::regclass),'RLS enabled '||t);foreach p in array array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE'] loop perform pg_temp.check_true(not has_table_privilege('anon','public.'||t,p),'anon denied '||p||' '||t);if p<>'SELECT' then perform pg_temp.check_true(not has_table_privilege('authenticated','public.'||t,p),'browser denied '||p||' '||t);end if;end loop;end loop;end;$$;
select pg_temp.check_true(not has_table_privilege('authenticated','workforce_private.time_off_operations','SELECT'),'receipt payloads private');
do $$declare f text;begin foreach f in array array['public.save_time_off(uuid,uuid,jsonb)','public.read_time_off_access(uuid)','public.read_time_off(uuid,text,text,text,integer,uuid,uuid,date,date,jsonb)'] loop perform pg_temp.check_true(not has_function_privilege('service_role',f,'EXECUTE'),'privileged app role denied '||f);end loop;end;$$;
select pg_temp.check_true(not has_function_privilege('anon','public.save_time_off(uuid,uuid,jsonb)','EXECUTE'),'anonymous mutation denied');
select pg_temp.check_true((select not prosecdef and provolatile='s' and proconfig @> array['search_path=""'] from pg_proc where oid='public.read_time_off(uuid,text,text,text,integer,uuid,uuid,date,date,jsonb)'::regprocedure),'read uses stable invoker snapshot');
