-- Count/paging/filter tests do not depend on a capped workforce directory.
insert into public.time_off_requests(tenant_id,agent_id,agent_name,type_id,type_name,type_description,type_paid,start_date,end_date,note,requested_by) select '81000000-0000-0000-0000-000000000001','84000000-0000-0000-0000-000000000804','Synthetic 804',t.id,t.name,t.description,t.paid,'2027-01-01','2027-01-01','Counted literal %_ '||n,'00000000-0000-0000-0000-000000000804' from public.time_off_types t,generate_series(1,1005)n;
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000801',false);
select pg_temp.check_true((public.read_time_off('81000000-0000-0000-0000-000000000001','team',search_text=>'Counted',page_limit=>1)->'counts'->>'total')::integer=1005,'exact counts exceed1000 with bounded page');
select pg_temp.check_true(jsonb_array_length(public.read_time_off('81000000-0000-0000-0000-000000000001','team',search_text=>'Counted',page_limit=>1)->'requests')=1,'request page respects bound');
select public.read_time_off('81000000-0000-0000-0000-000000000001','team',search_text=>'Counted',page_limit=>1) as counted_page \gset
select pg_temp.check_true(:'counted_page'::jsonb->'requests'->0->>'id'<>public.read_time_off('81000000-0000-0000-0000-000000000001','team',search_text=>'Counted',page_limit=>1,after_request=>:'counted_page'::jsonb->'nextCursor')->'requests'->0->>'id','stable keyset excludes boundary');
select pg_temp.check_true((public.read_time_off('81000000-0000-0000-0000-000000000001','team','pending')->'counts'->>'cancelled')::integer>0,'status counters precede selected status');
select pg_temp.check_true((public.read_time_off('81000000-0000-0000-0000-000000000001','team',search_text=>'%_')->'counts'->>'total')::integer=1005,'literal search does not treat wildcard tokens specially');
select pg_temp.check_true((public.read_time_off('81000000-0000-0000-0000-000000000001','team',start_date=>'2026-11-02',end_date=>'2026-11-02')->'counts'->>'total')::integer=1,'inclusive date filter selects overlapping calendar ranges');
select pg_temp.denied(format($q$select public.read_time_off('81000000-0000-0000-0000-000000000001','team',search_text=>'Changed',after_request=>%L::jsonb)$q$,:'counted_page'::jsonb->'nextCursor'),'22023','cursor bound to query scope');
select pg_temp.denied($q$select public.read_time_off('81000000-0000-0000-0000-000000000001','team',page_limit=>101)$q$,'22023','page over100 denied');
